#pragma once
#include "InputLevelCore.h"
#include <juce_core/juce_core.h>
#include <map>
struct InputRoutePreferences {
 std::array<InputLevels::Route,4> routes{};
 std::vector<InputLevels::Route> extraRoutes;
 std::vector<InputLevels::Source> monitoredInputs;
 std::map<std::string,std::string> friendlyNames;
 juce::String outputDevice;int outputChannel=0;bool outputStored=false;double pinkDb=-40.,sweepDb=-40.,sweepStart=20.,sweepEnd=20000.,sweepSeconds=5.;
 juce::var encode()const{auto* object=new juce::DynamicObject();object->setProperty("schema",monitoredInputs.empty()&&friendlyNames.empty()?(extraRoutes.empty()?1:2):3);juce::Array<juce::var> list;auto add=[&](const InputLevels::Route& r){auto* row=new juce::DynamicObject();row->setProperty("device",juce::String::fromUTF8(r.device.c_str()));row->setProperty("mic",r.mic);row->setProperty("ref",r.ref);list.add(juce::var(row));};for(const auto& r:routes)add(r);for(const auto& r:extraRoutes)add(r);object->setProperty("routes",list);juce::Array<juce::var> monitors;for(const auto& source:monitoredInputs){auto* row=new juce::DynamicObject();row->setProperty("device",juce::String::fromUTF8(source.device.c_str()));row->setProperty("channel",source.channel);monitors.add(juce::var(row));}object->setProperty("monitoredInputs",monitors);juce::Array<juce::var> labels;for(const auto& [key,name]:friendlyNames){auto* row=new juce::DynamicObject();row->setProperty("key",juce::String::fromUTF8(key.c_str()));row->setProperty("name",juce::String::fromUTF8(name.c_str()));labels.add(juce::var(row));}object->setProperty("friendlyNames",labels);object->setProperty("outputDevice",outputDevice);object->setProperty("outputChannel",outputChannel);object->setProperty("pinkDb",pinkDb);object->setProperty("sweepDb",sweepDb);object->setProperty("sweepStart",sweepStart);object->setProperty("sweepEnd",sweepEnd);object->setProperty("sweepSeconds",sweepSeconds);return juce::var(object);}
 static std::optional<InputRoutePreferences> read(const juce::File& file){auto v=juce::JSON::parse(file);int schema=int(v["schema"]);if(!v.isObject()||(schema!=1&&schema!=2&&schema!=3)||!v["routes"].isArray()||v["routes"].getArray()->size()<4||(schema==1&&v["routes"].getArray()->size()!=4))return {};InputRoutePreferences result;for(int i=0;i<v["routes"].getArray()->size();++i){auto row=v["routes"].getArray()->getReference(i);if(!row["device"].isString()||!row["mic"].isInt()||!row["ref"].isInt())return {};int m=int(row["mic"]),r=int(row["ref"]);if(m<0||r<0||m>InputLevels::maxChannels||r>InputLevels::maxChannels)return {};InputLevels::Route route{row["device"].toString().toStdString(),m,r};if(i<4)result.routes[(size_t)i]=route;else result.extraRoutes.push_back(route);}if(schema==3){if(!v["monitoredInputs"].isArray())return {};for(const auto& item:*v["monitoredInputs"].getArray()){if(!item["device"].isString()||!item["channel"].isInt())return {};int channel=int(item["channel"]);if(channel<1||channel>InputLevels::maxChannels)return {};result.monitoredInputs.push_back({item["device"].toString().toStdString(),channel});}}if(schema==3&&v["friendlyNames"].isArray())for(const auto& item:*v["friendlyNames"].getArray())if(item["key"].isString()&&item["name"].isString())result.friendlyNames[item["key"].toString().toStdString()]=item["name"].toString().toStdString();if(v.hasProperty("outputDevice")||v.hasProperty("outputChannel")){if(!v["outputDevice"].isString()||!v["outputChannel"].isInt()||int(v["outputChannel"])<0||int(v["outputChannel"])>InputLevels::stereoOutput)return {};result.outputDevice=v["outputDevice"].toString();result.outputChannel=int(v["outputChannel"]);result.outputStored=true;}if(v.hasProperty("pinkDb"))result.pinkDb=double(v["pinkDb"]);if(v.hasProperty("sweepDb"))result.sweepDb=double(v["sweepDb"]);if(v.hasProperty("sweepStart"))result.sweepStart=double(v["sweepStart"]);if(v.hasProperty("sweepSeconds"))result.sweepSeconds=double(v["sweepSeconds"]);if(v.hasProperty("sweepEnd"))result.sweepEnd=double(v["sweepEnd"]);return result;}
 std::vector<InputLevels::Route> allRoutes()const{std::vector<InputLevels::Route> result(routes.begin(),routes.end());result.insert(result.end(),extraRoutes.begin(),extraRoutes.end());return result;}
 bool save(const juce::File& file)const{juce::TemporaryFile tmp(file);return tmp.getFile().replaceWithText(juce::JSON::toString(encode()))&&tmp.overwriteTargetFileWithTemporary();}
};
